248	// bulkRepos builds n minimal project repos named <prefix>-0000…, for tests
249	// that need to cross the fetch budget.
250	func bulkRepos(prefix string, n int) []coreapi.Repo {
251		repos := make([]coreapi.Repo, 0, n)
252		for i := range n {
253			repos = append(repos, coreapi.Repo{
254				ID:              fmt.Sprintf("%s-%04d", prefix, i),
255				Name:            fmt.Sprintf("%s-%04d", prefix, i),
256				OwningProjectId: testProjectULID,
257			})
258		}
259		return repos
260	}
