262	// serveProjectRepos stands up a fake control-plane serving keyset-paginated
263	// GET /projects/{id}/repos: each call answers with the page addressed by the
264	// pageToken query param ("" is the first page). Every request is delivered on
265	// the returned channel (buffered to the page count so the handler never
266	// blocks). Points the active-context client seam at the server.
267	func serveProjectRepos(t *testing.T, pages []coreapi.ListProjectReposOutputBody) <-chan recordedRequest {
268		t.Helper()
269		tokenToPage := make(map[string]coreapi.ListProjectReposOutputBody, len(pages))
270		for i, p := range pages {
271			token := ""
272			if i > 0 {
273				token = pages[i-1].NextPageToken.Or("")
274				require.NotEmpty(t, token, "every page but the last needs a NextPageToken linking to the next one")
275			}
276			tokenToPage[token] = p
277		}
278		recCh := make(chan recordedRequest, len(pages))
279		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
280			w.Header().Set("Content-Type", "application/json")
281			if r.URL.Path != "/api/v1/projects/"+testProjectULID+"/repos" {
282				t.Errorf("unexpected path %q", r.URL.Path)
283				w.WriteHeader(http.StatusNotFound)
284				return
285			}
286			page, ok := tokenToPage[r.URL.Query().Get("pageToken")]
287			if !ok {
288				t.Errorf("unexpected pageToken %q", r.URL.Query().Get("pageToken"))
289				w.WriteHeader(http.StatusBadRequest)
290				return
291			}
292			if err := printJSON(w, &page); err != nil {
293				t.Errorf("encode repos response: %v", err)
294			}
295			recCh <- recordedRequest{method: r.Method, path: r.URL.Path, query: r.URL.Query()}
296		}))
297		t.Cleanup(srv.Close)
298	
299		prev := activeCoreClient
300		activeCoreClient = func(context.Context) (*coreapi.Client, error) {
301			return coreapi.NewWithBearer(srv.URL, "tok")
302		}
303		t.Cleanup(func() { activeCoreClient = prev })
304		return recCh
305	}
