55	
56		t.Run("concatenates pages until empty cursor", func(t *testing.T) {
57			t.Parallel()
58			// Three pages keyed by the cursor the previous page returned: "" -> a,
59			// "c1" -> b, "c2" -> c (last, empty next).
60			pages := map[string]struct {
61				items []string
62				next  string
63			}{
64				"":   {items: []string{"a", "b"}, next: "c1"},
65				"c1": {items: []string{"c", "d"}, next: "c2"},
66				"c2": {items: []string{"e"}, next: ""},
67			}
68			var calls int
69			got, err := fetchAllPages(context.Background(), func(_ context.Context, cursor string) ([]string, string, error) {
70				calls++
71				p := pages[cursor]
72				return p.items, p.next, nil
73			})
74			if err != nil {
75				t.Fatalf("fetchAllPages: %v", err)
76			}
77			if want := []string{"a", "b", "c", "d", "e"}; fmt.Sprint(got) != fmt.Sprint(want) {
78				t.Errorf("items = %v, want %v", got, want)
79			}
80			if calls != 3 {
81				t.Errorf("fetch calls = %d, want 3", calls)
82			}
83		})
